            {f.view === "map" ? (
              <div className="absolute inset-x-0 bottom-4 z-30 flex justify-center px-4">
                <div className="flex items-center gap-2">
                  <span className="dc-card px-3 py-2 text-[14px] font-semibold shadow-md">
